#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int m;
    long long target;
    if (!(cin >> m >> target)) m = 0;
    vector<string> tokens(m);
    for (auto &t : tokens) cin >> t;
    if (m == 0 || tokens[0] == "null") {
        cout << 0 << "\n";
        return 0;
    }
    // Build the tree from the level order: each non-null parent takes the next two tokens.
    vector<long long> values{stoll(tokens[0])};
    vector<int> parent{-1};
    vector<vector<int>> children(1);
    size_t q = 0;
    int i = 1;
    while (q < values.size() && i < m) {
        for (int side = 0; side < 2 && i < m; side++) {
            const string &token = tokens[i++];
            if (token != "null") {
                int v = values.size();
                values.push_back(stoll(token));
                parent.push_back(q);
                children.emplace_back();
                children[q].push_back(v);
            }
        }
        q++;
    }
    int n = values.size();
    vector<int> rank(n, 0);
    vector<long long> sums(n, 0);
    sums[0] = values[0];
    vector<int> layer{0};
    while (!layer.empty()) {
        int best = -1;
        for (int u : layer)
            if (children[u].empty() && sums[u] == target && (best < 0 || rank[u] < rank[best])) best = u;
        if (best >= 0) {
            vector<long long> path;
            for (int u = best; u != -1; u = parent[u]) path.push_back(values[u]);
            reverse(path.begin(), path.end());
            cout << path.size() << "\n";
            for (size_t k = 0; k < path.size(); k++) cout << (k ? " " : "") << path[k];
            cout << "\n";
            return 0;
        }
        vector<int> following;
        for (int u : layer)
            for (int v : children[u]) {
                sums[v] = sums[u] + values[v];
                following.push_back(v);
            }
        // Lexicographic rank of a path = rank of (parent path rank, own value).
        auto key = [&](int v) { return make_pair(rank[parent[v]], values[v]); };
        stable_sort(following.begin(), following.end(), [&](int a, int b) { return key(a) < key(b); });
        int r = -1;
        for (size_t k = 0; k < following.size(); k++) {
            if (k == 0 || key(following[k]) != key(following[k - 1])) r++;
            rank[following[k]] = r;
        }
        layer = following;
    }
    cout << 0 << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String first = next();
        int m = first.isEmpty() ? 0 : Integer.parseInt(first);
        long target = m == 0 ? 0 : nextLong();
        String[] tokens = new String[m];
        for (int i = 0; i < m; i++) tokens[i] = next();
        if (m == 0 || tokens[0].equals("null")) {
            System.out.println(0);
            return;
        }
        // Build the tree from the level order: each non-null parent takes the next two tokens.
        int cap = m;
        long[] values = new long[cap];
        int[] parent = new int[cap], left = new int[cap], right = new int[cap];
        Arrays.fill(left, -1);
        Arrays.fill(right, -1);
        values[0] = Long.parseLong(tokens[0]);
        parent[0] = -1;
        int n = 1, q = 0, i = 1;
        while (q < n && i < m) {
            for (int side = 0; side < 2 && i < m; side++) {
                String token = tokens[i++];
                if (!token.equals("null")) {
                    values[n] = Long.parseLong(token);
                    parent[n] = q;
                    if (side == 0) left[q] = n;
                    else right[q] = n;
                    n++;
                }
            }
            q++;
        }
        int[] rank = new int[n];
        long[] sums = new long[n];
        sums[0] = values[0];
        int[] layer = {0};
        while (layer.length > 0) {
            int best = -1;
            for (int u : layer)
                if (left[u] < 0 && right[u] < 0 && sums[u] == target && (best < 0 || rank[u] < rank[best])) best = u;
            if (best >= 0) {
                ArrayList<Long> path = new ArrayList<>();
                for (int u = best; u != -1; u = parent[u]) path.add(values[u]);
                Collections.reverse(path);
                StringBuilder sb = new StringBuilder();
                sb.append(path.size()).append('\n');
                for (int k = 0; k < path.size(); k++) {
                    if (k > 0) sb.append(' ');
                    sb.append(path.get(k));
                }
                System.out.println(sb);
                return;
            }
            int count = 0;
            for (int u : layer) count += (left[u] >= 0 ? 1 : 0) + (right[u] >= 0 ? 1 : 0);
            Integer[] following = new Integer[count];
            int f = 0;
            for (int u : layer)
                for (int v : new int[] {left[u], right[u]})
                    if (v >= 0) {
                        sums[v] = sums[u] + values[v];
                        following[f++] = v;
                    }
            // Lexicographic rank of a path = rank of (parent path rank, own value).
            final int[] rk = rank;
            final long[] vals = values;
            final int[] par = parent;
            Comparator<Integer> byKey = (a, b) -> rk[par[a]] != rk[par[b]]
                ? Integer.compare(rk[par[a]], rk[par[b]]) : Long.compare(vals[a], vals[b]);
            Arrays.sort(following, byKey);
            // Ranks of the parents are untouched here, so the keys stay stable while assigning.
            int r = -1;
            int[] nextLayer = new int[count];
            for (int k = 0; k < count; k++) {
                if (k == 0 || byKey.compare(following[k], following[k - 1]) != 0) r++;
                nextLayer[k] = following[k];
                rank[nextLayer[k]] = r;
            }
            layer = nextLayer;
        }
        System.out.println(0);
    }
}

