import (
	"fmt"
	"io"
	"os"
	"slices"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	first := token()
	m := 0
	if len(first) > 0 {
		m, _ = strconv.Atoi(string(first))
	}
	target := 0
	if m > 0 {
		target = nextInt()
	}
	tokens := make([]string, m)
	for i := range tokens {
		tokens[i] = string(token())
	}
	if m == 0 || tokens[0] == "null" {
		fmt.Println(0)
		return
	}
	// Build the tree from the level order: each non-null parent takes the next two tokens.
	v0, _ := strconv.Atoi(tokens[0])
	values := []int{v0}
	parent := []int{-1}
	children := [][]int{nil}
	q, i := 0, 1
	for q < len(values) && i < m {
		for side := 0; side < 2 && i < m; side++ {
			tok := tokens[i]
			i++
			if tok != "null" {
				val, _ := strconv.Atoi(tok)
				v := len(values)
				values = append(values, val)
				parent = append(parent, q)
				children = append(children, nil)
				children[q] = append(children[q], v)
			}
		}
		q++
	}
	n := len(values)
	rank := make([]int, n)
	sums := make([]int, n)
	sums[0] = values[0]
	layer := []int{0}
	for len(layer) > 0 {
		best := -1
		for _, u := range layer {
			if len(children[u]) == 0 && sums[u] == target && (best < 0 || rank[u] < rank[best]) {
				best = u
			}
		}
		if best >= 0 {
			path := []string{}
			for u := best; u != -1; u = parent[u] {
				path = append(path, strconv.Itoa(values[u]))
			}
			slices.Reverse(path)
			fmt.Println(len(path))
			fmt.Println(strings.Join(path, " "))
			return
		}
		following := []int{}
		for _, u := range layer {
			for _, v := range children[u] {
				sums[v] = sums[u] + values[v]
				following = append(following, v)
			}
		}
		// Lexicographic rank of a path = rank of (parent path rank, own value).
		cmp := func(a, b int) int {
			if rank[parent[a]] != rank[parent[b]] {
				return rank[parent[a]] - rank[parent[b]]
			}
			if values[a] < values[b] {
				return -1
			}
			if values[a] > values[b] {
				return 1
			}
			return 0
		}
		slices.SortStableFunc(following, cmp)
		newRank := make([]int, len(following))
		r := -1
		for k, v := range following {
			if k == 0 || cmp(v, following[k-1]) != 0 {
				r++
			}
			newRank[k] = r
		}
		for k, v := range following {
			rank[v] = newRank[k]
		}
		layer = following
	}
	fmt.Println(0)
}
